from mpi4py import MPI
import numpy as np
import math

def sign(x, y):
    """Fortran SIGN function: returns |x| * sign(y)"""
    if y >= 0:
        return abs(x)
    else:
        return -abs(x)

def householder_bidiagonal_mpi():
    """Parallel MPI implementation of Householder bidiagonalization"""
    comm = MPI.COMM_WORLD
    rank = comm.Get_rank()
    size = comm.Get_size()

    # Assume matrix is distributed in 2D block-cyclic format (simplified)
    # For demonstration, we'll use a simple 1D row distribution
    N = 10  # Matrix size - would normally be read from input

    # Create local matrix block
    local_rows = N // size
    if rank == size - 1:
        local_rows = N - rank * local_rows

    # Initialize local matrix A (distributed by rows)
    A = np.zeros((local_rows, N))

    # Only root initializes the full matrix
    if rank == 0:
        full_A = np.random.rand(N, N)

    # Distribute rows to processes
    row_counts = [N // size] * size
    row_counts[-1] = N - (size-1) * (N // size)

    # Scatter the matrix rows
    comm.Scatterv([full_A, row_counts * N, MPI.DOUBLE], A, root=0)

    # Local start index
    local_start = rank * (N // size)
    if rank == size - 1:
        local_start = N - local_rows

    # Householder bidiagonalization
    for i in range(N-1):
        # === First step: Column Householder reflection ===

        # Compute local part of vector SX (norm computation)
        SX_local = np.zeros(N)
        for k in range(i, N):
            for j in range(local_start, min(local_start + local_rows, N)):
                if j >= i:
                    SX_local[k] += A[j-local_start, i] * A[j-local_start, k]

        # Global reduction to get complete SX
        SX = np.zeros(N)
        comm.Allreduce(SX_local, SX, op=MPI.SUM)

        ALPHA = math.sqrt(SX[i])

        # Find which process owns row i
        owner_rank = min(i // (N // size), size - 1) if N % size == 0 else None
        if owner_rank is None:
            # Handle uneven distribution
            cumulative = 0
            for r in range(size):
                rows_here = N // size if r < size-1 else N - (size-1)*(N//size)
                if cumulative + rows_here > i:
                    owner_rank = r
                    break
                cumulative += rows_here

        # Broadcast ALPHA from owner to all
        ALPHA = comm.bcast(ALPHA, root=owner_rank)

        if ALPHA != 0:
            BETA = 1.0 / ALPHA

            # Update subdiagonal elements in column i (only processes that have rows > i)
            if local_start > i or local_start + local_rows <= i:
                # This process doesn't have row i, but may have rows below
                for j in range(max(i+1, local_start), min(local_start + local_rows, N)):
                    A[j-local_start, i] *= BETA

            # Row i owner computes first element of SX
            if rank == owner_rank:
                if A[i-local_start, i] != 0:
                    SX[i] = A[i-local_start, i] * BETA + sign(1.0, A[i-local_start, i])
                else:
                    SX[i] = -1.0
                A[i-local_start, i] = ALPHA
                G = 1.0 / abs(SX[i])
            else:
                # Receive SX[i] and G from owner
                SX_i = None
                G = None

            # Broadcast SX[i] and G to all processes
            SX_i = comm.bcast(SX[i] if rank == owner_rank else None, root=owner_rank)
            G = comm.bcast(G if rank == owner_rank else None, root=owner_rank)

            if rank != owner_rank:
                SX[i] = SX_i

            # Update remaining columns
            for k in range(i+1, N):
                # Each process updates its local rows
                # First, compute contribution to SX[k]
                local_contribution = 0
                for j in range(max(i+1, local_start), min(local_start + local_rows, N)):
                    local_contribution += A[j-local_start, i] * (SX[k] * BETA * G + sign(A[i-local_start if rank == owner_rank else 0, k], SX[i]))

                # Reduce contributions to update A[i, k]
                global_contribution = comm.allreduce(local_contribution, op=MPI.SUM)

                if rank == owner_rank:
                    A[i-local_start, k] += global_contribution

                # Broadcast updated A[i, k] to all
                if rank == owner_rank:
                    aik = A[i-local_start, k]
                else:
                    aik = None
                aik = comm.bcast(aik, root=owner_rank)

                # Update local rows of column k
                for j in range(max(i+1, local_start), min(local_start + local_rows, N)):
                    A[j-local_start, k] -= A[j-local_start, i] * (SX[k] * BETA * G + sign(aik, SX[i]))

        # === Second step: Row Householder reflection (if i < N-2) ===
        if i < N-2:
            # Compute local part of vector SL
            SL_local = np.zeros(N)
            for k in range(i, N):
                for j in range(local_start, min(local_start + local_rows, N)):
                    if j >= i:
                        # Need row i, which is owned by owner_rank
                        # For simplicity, gather row i first
                        if rank == owner_rank:
                            row_i = A[i-local_start, :]
                        else:
                            row_i = np.zeros(N)
                        row_i = comm.bcast(row_i, root=owner_rank)

                        SL_local[k] += row_i[i] * A[j-local_start, k] if j == i else row_i[j] * A[j-local_start, k]

            # Global reduction for SL
            SL = np.zeros(N)
            comm.Allreduce(SL_local, SL, op=MPI.SUM)

            ALPHA = math.sqrt(SL[i])

            if ALPHA != 0:
                BETA = 1.0 / ALPHA

                # Row owner updates superdiagonal elements
                if rank == owner_rank:
                    for j in range(i+2, N):
                        A[i-local_start, j] *= BETA

                    if A[i-local_start, i+1] != 0:
                        SL[i] = A[i-local_start, i+1] * BETA + sign(1.0, A[i-local_start, i+1])
                    else:
                        SL[i] = -1.0

                    A[i-local_start, i+1] = ALPHA
                    G = 1.0 / abs(SL[i])

                    # Update row i
                    for k in range(i+1, N):
                        SL_k = SL[k] * BETA * G + sign(A[i-local_start, k+1] if k+1 < N else 0, SL[i])
                        if k+1 < N:
                            A[i-local_start, k+1] += SL_k * SL[i]

                        # Update column i+1 and beyond
                        for j in range(i+2, N):
                            A[i-local_start, j] -= A[i-local_start, j] * SL_k

                # Broadcast updated row i to all processes
                if rank == owner_rank:
                    updated_row_i = A[i-local_start, :]
                else:
                    updated_row_i = np.zeros(N)
                updated_row_i = comm.bcast(updated_row_i, root=owner_rank)

                # Update local matrix with row Householder reflection
                for j in range(max(i+2, local_start), min(local_start + local_rows, N)):
                    for k in range(i+2, N):
                        A[j-local_start, k] -= updated_row_i[j] * SL[k]

    # Gather results back to root
    comm.Barrier()
    if rank == 0:
        result = np.zeros((N, N))
    else:
        result = None

    comm.Gatherv(A, [result, row_counts * N, MPI.DOUBLE], root=0)

    if rank == 0:
        # Extract bidiagonal form
        D = np.diag(np.diag(result))
        E = np.diag(np.diag(result, 1), 1)
        print("Bidiagonal matrix B = D + E:")
        print(D + E)

if __name__ == "__main__":
    householder_bidiagonal_mpi()
